import { agents } from './data.js';
const html=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const agentName=id=>agents.find(agent=>agent.id===id)?.name||id;
const time=value=>{const date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('it-IT',{hour:'2-digit',minute:'2-digit'}).format(date):'a breve';};

export function createPlanningPanel({toast=()=>{},onCommit=()=>{}}={}) {
  const dialog=document.createElement('dialog');dialog.id='plans-dialog';dialog.className='ops-dialog plan-dialog';dialog.setAttribute('aria-labelledby','plan-dialog-title');document.body.append(dialog);
  let project=null,brief='',draft=null,saving=false,busy=false,expiryTimer=null,sessionExpired=false;
  async function request(action,payload){const response=await fetch('/api/plans',{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:JSON.stringify({action,payload})});let value;try{value=await response.json();}catch{throw Error('Riccardo non ha restituito una proposta valida.');}if(sessionExpired)throw Error('Sessione scaduta.');if(!response.ok)throw Error(value.error||'Non è stato possibile completare la richiesta.');return value;}
  function sync(){dialog.querySelectorAll('[data-plan-mutation]').forEach(el=>el.disabled=saving||busy||(el.dataset.planAction==='commit'&&new Date(draft?.expiresAt).getTime()<=Date.now()));}
  function shell(title,body,footer){dialog.innerHTML=`<div class="ops-dialog-heading"><div><div class="eyebrow">PIANIFICA CON RICCARDO</div><h2 id="plan-dialog-title">${html(title)}</h2></div><button type="button" class="ops-icon" data-plan-action="close" aria-label="Chiudi finestra">✕</button></div>${body}<div class="ops-dialog-footer">${footer}</div>`;if(!dialog.open)dialog.showModal();sync();}
  function showForm(){clearTimeout(expiryTimer);draft=null;shell('Dall’obiettivo a un piano',`<form id="plan-form"><div class="ops-form-body"><p class="ops-form-intro"><strong>${html(project.title)}</strong>. Riccardo proporrà incarichi, responsabili e dipendenze da controllare prima di crearli.</p><div class="ops-field"><label for="plan-brief">Obiettivo e vincoli del piano</label><textarea id="plan-brief" name="brief" required maxlength="12000" rows="7">${html(brief)}</textarea><p class="ops-hint">Descrivi il risultato desiderato, le informazioni disponibili e i criteri di riuscita. I passaggi lavoreranno sui materiali autorizzati del progetto.</p></div><div class="plan-consumption"><span aria-hidden="true">✳</span><p><strong>Generare la proposta chiama il servizio AI di Riccardo.</strong> Può produrre consumo sul relativo account. La generazione non avvia gli incarichi proposti.</p></div></div><p class="ops-form-error" role="alert" hidden></p></form>`,`<button type="button" class="ops-button" data-plan-action="close">Annulla</button><button type="submit" form="plan-form" class="ops-button is-primary" data-plan-mutation>Genera proposta con Riccardo</button>`);
    dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();if(saving||busy)return;const form=event.currentTarget;if(!form.reportValidity())return;brief=new FormData(form).get('brief').trim();const error=dialog.querySelector('.ops-form-error'),button=dialog.querySelector('[type="submit"]');saving=true;error.hidden=true;button.textContent='Riccardo sta preparando il piano…';sync();try{const value=await request('draft',{projectId:project.id,brief});if(!value?.id||!Array.isArray(value.nodes)||!value.nodes.length)throw Error('La proposta non contiene incarichi validi.');draft=value;saving=false;preview();}catch(e){error.textContent=e.message;error.hidden=false;button.textContent='Genera proposta con Riccardo';}finally{saving=false;sync();}});
  }
  function preview(){const expired=new Date(draft.expiresAt).getTime()<=Date.now(),keys=new Map(draft.nodes.map((node,i)=>[node.key,i]));shell(draft.title||'Controlla la proposta',`<div class="ops-task-body plan-preview"><div class="plan-preview-meta"><span>${draft.nodes.length} incarichi proposti</span><span>Scade alle ${html(time(draft.expiresAt))}</span></div><p class="ops-form-intro">Controlla cosa farà ciascun agente e quali risultati deve attendere. Confermando crei gli incarichi <strong>da avviare</strong>; non vengono eseguite altre chiamate AI.</p><ol class="plan-nodes">${draft.nodes.map((node,i)=>`<li id="plan-node-${i}"><span class="plan-node-number">${i+1}</span><article><div class="plan-node-heading"><h3>${html(node.title)}</h3><span>${html(agentName(node.agentId))}</span></div><p>${html(node.brief)}</p><div class="plan-dependencies">${node.dependsOn?.length?`<strong>Attende l’approvazione di</strong>${node.dependsOn.map(key=>`<a href="#plan-node-${keys.get(key)}" data-plan-node="${keys.get(key)}">${(keys.get(key)??0)+1}. ${html(draft.nodes[keys.get(key)]?.title||key)}</a>`).join('')}`:'<span>Può partire senza incarichi precedenti</span>'}</div></article></li>`).join('')}</ol><p class="plan-notice">I passaggi dipendenti si sbloccano quando tutte le consegne precedenti sono completate e approvate. Avvii tu ogni incarico.</p><p class="ops-form-error" role="alert"${expired?'':' hidden'}>${expired?'Questa proposta è scaduta. Torna al brief e genera una nuova proposta.':''}</p></div>`,`<button type="button" class="ops-button" data-plan-action="close">Chiudi</button><button type="button" class="ops-button" data-plan-action="back">Torna al brief</button><button type="button" class="ops-button is-primary" data-plan-action="commit" data-plan-mutation>Crea ${draft.nodes.length} incarichi da avviare</button>`);clearTimeout(expiryTimer);const remaining=new Date(draft.expiresAt).getTime()-Date.now();if(remaining>0)expiryTimer=setTimeout(()=>{if(draft&&dialog.open&&!saving)preview();},Math.min(remaining,2147483647));}
  dialog.addEventListener('click',async event=>{const node=event.target.closest('[data-plan-node]');if(node){event.preventDefault();dialog.querySelector(`#plan-node-${node.dataset.planNode}`)?.scrollIntoView({block:'center',behavior:'smooth'});return;}const button=event.target.closest('[data-plan-action]');if(!button||button.disabled||saving)return;const action=button.dataset.planAction;if(action==='close'){dialog.close();return;}if(action==='back'){showForm();return;}if(action!=='commit'||busy||!draft)return;saving=true;sync();const error=dialog.querySelector('.ops-form-error');error.hidden=true;try{const value=await request('commit',{id:draft.id});onCommit(value);dialog.close();toast('Piano creato. Gli incarichi aspettano il tuo avvio, rispettando le dipendenze.');}catch(e){error.textContent=e.message;error.hidden=false;}finally{saving=false;sync();}});
  dialog.addEventListener('cancel',event=>{if(saving)event.preventDefault();});dialog.addEventListener('close',()=>{if(!dialog.open)clearTimeout(expiryTimer);});
  function expire(){sessionExpired=true;if(dialog.open)dialog.close();clearTimeout(expiryTimer);}
  window.addEventListener('studio-session-expired',expire);
  return {open(value){if(busy||saving)return;project=value;brief='';showForm();},setBusy(value){busy=Boolean(value);sync();},dispose(){clearTimeout(expiryTimer);window.removeEventListener('studio-session-expired',expire);dialog.remove();}};
}
